#chat .mes .mes_buttons>:is(.mes_edit,.fa-pencil){--orbit-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/starry-flow/4.webp');}
#chat .mes .mes_buttons>:is(.mes_copy,.fa-layer-group){--orbit-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/starry-flow/5.webp');}
#chat .mes .mes_buttons>:is(.fa-chart-bar,.fa-chart-simple,[title*="统计"]){--orbit-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/starry-flow/6.webp');}
