#top-settings-holder>.drawer:nth-child(6) .drawer-icon{width:26px!important;height:30px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-2.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(6) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(7) .drawer-icon{width:26px!important;height:30px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-3.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(7) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(8) .drawer-icon{width:26px!important;height:30px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/starry/icon-4.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(8) .drawer-icon::before{opacity:0!important;}
