#chat .mes .mes_buttons>:not(.extraMesButtons){transform:none!important;flex:0 0 34px!important;width:34px!important;height:34px!important;min-width:34px!important;min-height:34px!important;background-image:var(--orbit-action,url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/starry-flow/0.webp'))!important;}
