/* Follow the original wave, excluding the expanded menu and hidden actions. */
#chat .mes .mes_buttons{margin-bottom:14px!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons){transform:translateY(var(--wave-y,0px))!important;}

#chat .mes .mes_buttons>:nth-child(1 of :not(.extraMesButtons):not(.displayNone):not(.hidden):not([hidden]):not([style*="display: none"]):not([style*="display:none"])){--wave-y:-5px;}
#chat .mes .mes_buttons>:nth-child(2 of :not(.extraMesButtons):not(.displayNone):not(.hidden):not([hidden]):not([style*="display: none"]):not([style*="display:none"])){--wave-y:2px;}
