/* ===== 平板修正（追加在最后，原版内容没动） ===== */
/* 1. 平板打开预设/角色面板只剩一条：打开时从顶栏下面铺到屏幕底 */
.fillLeft.openDrawer,.fillRight.openDrawer{position:fixed!important;top:var(--topBarBlockSize)!important;height:calc(100dvh - var(--topBarBlockSize))!important;max-height:calc(100dvh - var(--topBarBlockSize))!important}
#top-settings-holder .drawer-content:not(.fillLeft):not(.fillRight){max-height:calc(100dvh - var(--topBarBlockSize) - 8px)!important}
/* 2. 平板横屏时对话只占中间一半：改成铺满 */
#sheld,#top-bar,#top-settings-holder{width:100%!important;max-width:100%!important;left:0!important;right:0!important;margin-inline:0!important}
/* 3. 平板上楼层/用时/字数太小 */
@media(min-width:600px){
 #chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{font-size:12px!important;line-height:18px!important}
 #chat .mes .timestamp{font-size:11px!important}
 #chat .mes{max-width:min(900px,100%)!important}
}
/* 4. 思考框跟主题配色 */
#chat .mes .mes_reasoning_details{grid-column:1/-1!important;margin:6px 0!important}
#chat .mes .mes_reasoning_header{background:rgba(21,48,78,.85)!important;color:#ecdcad!important;border:1px solid #3d5677!important;border-radius:999px!important}
#chat .mes .mes_reasoning{max-height:min(280px,40dvh);overflow:auto;overscroll-behavior:contain;background:rgba(16,40,68,.7)!important;color:#d9e1f5!important;border:1px solid #3d5677!important;border-radius:10px!important;padding:10px 12px!important}
/* 5. 生成的图片保持原比例 */
#chat .mes :is(.mes_text,.mes_reasoning) img[height],#chat .mes :is(.mes_text,.mes_reasoning) img[width]{height:auto!important;max-width:100%!important}
#chat .mes .mes_img{height:auto!important;width:auto!important;max-width:100%!important;object-fit:contain!important}
/* 6. 禁止下拉刷新整页 */
html,body{overscroll-behavior:none!important}
#chat,.drawer-content{overscroll-behavior:contain!important}

/* 仅补齐原头像框两侧：原素材、取景位置与其他布局不变。 */
#chat .mes .avatar::before{content:"";position:absolute;inset:0;z-index:2;pointer-events:none;background:url("https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/starry-flow/side-repair.webp") center/contain no-repeat;mask-image:linear-gradient(to right,#000 0%,#000 5%,transparent 8%,transparent 92%,#000 95%,#000 100%);-webkit-mask-image:linear-gradient(to right,#000 0%,#000 5%,transparent 8%,transparent 92%,#000 95%,#000 100%);}
#chat .mes .avatar::after{z-index:3;}
#chat .mes .avatar img{clip-path:inset(15% 1.5% 17% 1.5%)!important;}
